def find_x(g):
    # X = 3x3 pattern with 2s at corners(center? no: arms) -- actually X: center cell 2? In demos, center cell is 0!
    # pattern: 2 at (0,1),(1,0),(1,2),(2,1); center (1,1)=0
    H,W=len(g),len(g[0]); c=[]
    for i in range(1,H-1):
        for j in range(1,W-1):
            if g[i-1][j]==2 and g[i][j-1]==2 and g[i][j+1]==2 and g[i+1][j]==2 and g[i][j]==0 and g[i-1][j-1]==0 and g[i+1][j+1]==0 and g[i-1][j+1]==0 and g[i+1][j-1]==0:
                c.append((i,j))
    return c
