    g=[r[:] for r in g]
    cs=find_x(g)
    for a in range(len(cs)):
        for b in range(a+1,len(cs)):
            (r1,c1),(r2,c2)=cs[a],cs[b]
            if c1==c2 and r1!=r2:
                lo,hi=sorted((r1,r2))
                if all(g[i][c1]==0 for i in range(lo+2,hi-1)):
